var ENT=[["Loader", "Signature Loader pillar of the Model Context Manager framework."], ["Quantizer", "Signature Quantizer pillar of the Model Context Manager framework."], ["Router", "Signature Router pillar of the Model Context Manager framework."], ["Streamer", "Signature Streamer pillar of the Model Context Manager framework."], ["Budgeter", "Signature Budgeter pillar of the Model Context Manager framework."], ["Validator", "Signature Validator pillar of the Model Context Manager framework."], ["Harness", "Signature Harness pillar of the Model Context Manager framework."]];
